CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TABLE public.couple_members (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, person text UNIQUE NOT NULL CHECK(person IN ('Daniel','Letícia')));
GRANT SELECT ON public.couple_members TO authenticated; GRANT ALL ON public.couple_members TO service_role;
ALTER TABLE public.couple_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_duet_member() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.couple_members WHERE user_id = auth.uid()) $$;
REVOKE ALL ON FUNCTION public.is_duet_member() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_duet_member() TO authenticated;
CREATE POLICY couple_read ON public.couple_members FOR SELECT TO authenticated USING (public.is_duet_member());
CREATE FUNCTION public.create_duet_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id); RETURN NEW; END $$;
CREATE TRIGGER duet_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_duet_profile();
CREATE TABLE public.references_catalog (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, description text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'Locais', city text NOT NULL DEFAULT '', state text NOT NULL DEFAULT '', scenery text NOT NULL DEFAULT '', source_url text NOT NULL, instagram_url text, verification text NOT NULL DEFAULT 'A confirmar', checked_at timestamptz NOT NULL DEFAULT now(), image_path text, image_credit text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_url,title));
GRANT SELECT, INSERT, UPDATE ON public.references_catalog TO authenticated; GRANT ALL ON public.references_catalog TO service_role;
ALTER TABLE public.references_catalog ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalog_read ON public.references_catalog FOR SELECT TO authenticated USING(public.is_duet_member());
CREATE POLICY catalog_add ON public.references_catalog FOR INSERT TO authenticated WITH CHECK(public.is_duet_member() AND created_by = auth.uid());
CREATE POLICY catalog_update ON public.references_catalog FOR UPDATE TO authenticated USING(public.is_duet_member()) WITH CHECK(public.is_duet_member());
CREATE TABLE public.records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK(kind IN ('goal','task','note','setting')), title text NOT NULL, body text NOT NULL DEFAULT '', period text NOT NULL DEFAULT 'Curto Prazo', reference_id uuid REFERENCES public.references_catalog(id), done boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 1, created_by uuid, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX duet_reference_goal ON public.records(reference_id) WHERE kind = 'goal' AND reference_id IS NOT NULL;
CREATE UNIQUE INDEX duet_setting ON public.records(title) WHERE kind = 'setting';
GRANT SELECT, INSERT, UPDATE, DELETE ON public.records TO authenticated; GRANT ALL ON public.records TO service_role;
ALTER TABLE public.records ENABLE ROW LEVEL SECURITY;
CREATE POLICY records_read ON public.records FOR SELECT TO authenticated USING(public.is_duet_member());
CREATE POLICY records_add ON public.records FOR INSERT TO authenticated WITH CHECK(public.is_duet_member() AND created_by = auth.uid() AND updated_by = auth.uid());
CREATE POLICY records_update ON public.records FOR UPDATE TO authenticated USING(public.is_duet_member()) WITH CHECK(public.is_duet_member() AND updated_by = auth.uid());
CREATE POLICY records_delete ON public.records FOR DELETE TO authenticated USING(public.is_duet_member());
CREATE TABLE public.votes (reference_id uuid NOT NULL REFERENCES public.references_catalog(id), user_id uuid NOT NULL REFERENCES public.profiles(id), liked boolean NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(reference_id,user_id));
GRANT SELECT, INSERT, UPDATE ON public.votes TO authenticated; GRANT ALL ON public.votes TO service_role;
ALTER TABLE public.votes ENABLE ROW LEVEL SECURITY;
CREATE POLICY votes_read ON public.votes FOR SELECT TO authenticated USING(public.is_duet_member());
CREATE POLICY votes_add ON public.votes FOR INSERT TO authenticated WITH CHECK(public.is_duet_member() AND user_id = auth.uid());
CREATE POLICY votes_update ON public.votes FOR UPDATE TO authenticated USING(public.is_duet_member() AND user_id = auth.uid()) WITH CHECK(public.is_duet_member() AND user_id = auth.uid());
CREATE TABLE public.signatures (record_id uuid NOT NULL REFERENCES public.records(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(record_id,user_id));
GRANT SELECT, INSERT ON public.signatures TO authenticated; GRANT ALL ON public.signatures TO service_role;
ALTER TABLE public.signatures ENABLE ROW LEVEL SECURITY;
CREATE POLICY signatures_read ON public.signatures FOR SELECT TO authenticated USING(public.is_duet_member());
CREATE POLICY signatures_add ON public.signatures FOR INSERT TO authenticated WITH CHECK(public.is_duet_member() AND user_id = auth.uid() AND EXISTS(SELECT 1 FROM public.records WHERE id = record_id AND kind = 'goal'));
CREATE TABLE public.activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, entity_id uuid NOT NULL, entity_type text NOT NULL, action text NOT NULL, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.activity TO authenticated; GRANT ALL ON public.activity TO service_role;
ALTER TABLE public.activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY activity_read ON public.activity FOR SELECT TO authenticated USING(public.is_duet_member());
CREATE FUNCTION public.duet_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE rowdata jsonb; eid uuid; BEGIN IF TG_OP = 'DELETE' THEN rowdata := to_jsonb(OLD); ELSE rowdata := to_jsonb(NEW); END IF; eid := COALESCE((rowdata->>'id')::uuid,(rowdata->>'reference_id')::uuid,(rowdata->>'record_id')::uuid); INSERT INTO public.activity(actor_id,entity_id,entity_type,action,snapshot) VALUES(auth.uid(),eid,TG_TABLE_NAME,TG_OP,rowdata); IF TG_OP = 'DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.duet_record_version() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.version <> OLD.version THEN RAISE EXCEPTION 'Conflito: este registro foi atualizado. Recarregue antes de salvar.'; END IF; NEW.version := OLD.version + 1; NEW.updated_at := now(); RETURN NEW; END $$;
CREATE TRIGGER records_version BEFORE UPDATE ON public.records FOR EACH ROW EXECUTE FUNCTION public.duet_record_version();
CREATE TRIGGER records_audit AFTER INSERT OR UPDATE OR DELETE ON public.records FOR EACH ROW EXECUTE FUNCTION public.duet_audit();
CREATE TRIGGER votes_audit AFTER INSERT OR UPDATE ON public.votes FOR EACH ROW EXECUTE FUNCTION public.duet_audit();
CREATE TRIGGER signatures_audit AFTER INSERT ON public.signatures FOR EACH ROW EXECUTE FUNCTION public.duet_audit();
ALTER PUBLICATION supabase_realtime ADD TABLE public.records, public.votes, public.signatures, public.references_catalog, public.activity;